<?php $sectionMetrics = ['Total de solicitudes' => count($solicitudes), 'Pendientes' => count(array_filter($solicitudes,static fn($s)=>$s['estado']==='Pendiente')), 'En proceso' => count(array_filter($solicitudes,static fn($s)=>$s['estado']==='En proceso'))]; ?>
<div class="module-metrics" aria-label="Indicadores de Solicitudes de diseño">
<?php foreach($sectionMetrics as $label=>$count): ?><div class="module-metric"><span><?= h($label) ?></span><strong><?= (int)$count ?></strong></div><?php endforeach; ?>
</div>
<section class="management-grid section-management" aria-label="Solicitudes de diseño">
<article class="dash-panel management" id="solicitudes" data-module="solicitudes"><div class="manage-title"><div class="manage-icon"><?= admIcon('file') ?></div><div><h2>Gestión de solicitudes</h2><small>Revisa y administra el estado de pedidos</small></div><button type="button" class="primary mini" id="newRequestButton" <?= !$disenosDisponibles?'disabled title="Necesitas diseños guardados"':'' ?>><?= admIcon('plus') ?> Nueva solicitud</button></div>
<div class="manage-filters"><label class="search-field"><?= admIcon('search') ?><input data-search type="search" placeholder="Buscar solicitud..."></label><select data-filter aria-label="Filtrar solicitudes"><option value="">Todos los estados</option><?php foreach(['Pendiente','En proceso','Aprobada','Rechazada','Finalizada','Archivada'] as $estado):?><option><?= h($estado) ?></option><?php endforeach; ?></select></div>
<div class="table-scroll"><table><thead><tr><th>ID</th><th>Usuario</th><th>Diseño</th><th>Fecha</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($solicitudes as $r):?><tr data-searchable="<?= h($r['id'].' '.$r['usuario'].' '.$r['diseno'].' '.$r['descripcion'].' '.$r['estado']) ?>" data-filter-value="<?= h($r['estado']) ?>"><td><?= (int)$r['id'] ?></td><td><?= h($r['usuario']) ?></td><td><?= h($r['diseno']) ?></td><td><?= h(date('d/m/Y',strtotime($r['creado_en']))) ?></td><td><?= stateBadge($r['estado']) ?></td><td class="actions"><button class="icon-action" data-request="<?= h(json_encode($r,JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)) ?>" title="Revisar solicitud" aria-label="Revisar"><?= admIcon('edit') ?></button></td></tr><?php endforeach; ?></tbody></table></div><div class="pagination"><span data-count></span><div data-pages></div></div></article>
</section>
